--
-- Name: mock_evidence_only(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.mock_evidence_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE s text;
BEGIN
  SELECT state INTO s FROM app.integration WHERE key = NEW.integration_key;
  IF s IS DISTINCT FROM 'VERIFIED' AND NEW.evidence <> 'SYNTHETIC_MOCK' THEN
    RAISE EXCEPTION 'integration % is %: only SYNTHETIC_MOCK evidence may be stored from it', NEW.integration_key, s USING ERRCODE = 'EM004';
  END IF;
  RETURN NEW;
END $$;

--
-- Name: next_code(text, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.next_code(k text, prefix text, width integer DEFAULT 4) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE v bigint;
BEGIN
  INSERT INTO app.code_counter (tenant_id, kind, value) VALUES (app.current_tenant(), k, 1)
    ON CONFLICT (tenant_id, kind) DO UPDATE SET value = app.code_counter.value + 1 RETURNING value INTO v;
  RETURN prefix || lpad(v::text, width, '0');
END $$;

--
-- Name: refuse_change(); Type: FUNCTION; Schema: app; Owner: -
