--
-- Name: result_only_in_commissioning(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.result_only_in_commissioning() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE l text;
BEGIN
  SELECT lifecycle INTO l FROM app.room WHERE id = NEW.room_id AND tenant_id = NEW.tenant_id;
  IF l IS DISTINCT FROM 'COMMISSIONING' THEN
    RAISE EXCEPTION 'results are recorded on a room in COMMISSIONING (this one is %)', l USING ERRCODE = 'EM002';
  END IF;
  RETURN NEW;
END $$;

--
-- Name: tenant_rls(regclass); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tenant_rls(tbl regclass) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', tbl);
  EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', tbl);
  EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %s', tbl);
  EXECUTE format('CREATE POLICY tenant_isolation ON %s USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant())', tbl);
END $$;

--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: app; Owner: -
