    model text DEFAULT 'generic'::text NOT NULL,
    generic boolean DEFAULT true NOT NULL,
    furniture boolean DEFAULT false NOT NULL,
    x numeric(9,2) NOT NULL,
    y numeric(9,2) NOT NULL,
    z numeric(6,2) DEFAULT 0 NOT NULL,
    rot numeric(6,1) DEFAULT 0 NOT NULL,
    mount text NOT NULL,
    props jsonb DEFAULT '{}'::jsonb NOT NULL,
    model_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    lifecycle text DEFAULT 'PLANNED'::text NOT NULL,
    removed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT planned_asset_code_check CHECK ((code ~ '^PA-[0-9]{4,10}$'::text))
);

ALTER TABLE ONLY app.planned_asset FORCE ROW LEVEL SECURITY;

