CREATE TABLE app.project (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    state text DEFAULT 'OPEN'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT project_code_format CHECK ((code ~ '^PRJ-[A-Z0-9-]{2,32}$'::text)),
    CONSTRAINT project_state_check CHECK ((state = ANY (ARRAY['OPEN'::text, 'CLOSED'::text])))
);

ALTER TABLE ONLY app.project FORCE ROW LEVEL SECURITY;

