);

--
-- Name: TABLE role; Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON TABLE app.role IS 'Global role catalogue. "*" (every authority) exists for the demonstration architect only and is never granted by the seed to a production tenant.';

--
-- Name: room; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.room (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    building_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    floor integer DEFAULT 1 NOT NULL,
    template text NOT NULL,
    intended_use text DEFAULT ''::text NOT NULL,
    occupancy integer NOT NULL,
    unit text DEFAULT 'm'::text NOT NULL,
    geometry jsonb NOT NULL,
    lifecycle text DEFAULT 'PLANNED'::text NOT NULL,
    classification jsonb,
    approved_class jsonb,
    rev integer DEFAULT 1 NOT NULL,
    approved_revision integer,
    baseline jsonb,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    project_id uuid,
    CONSTRAINT room_code_check CHECK ((code ~ '^R-[A-Z0-9-]{3,32}$'::text)),
    CONSTRAINT room_geometry_check CHECK ((jsonb_typeof((geometry -> 'points'::text)) = 'array'::text)),
    CONSTRAINT room_lifecycle_check CHECK ((lifecycle = ANY (ARRAY['PLANNED'::text, 'DESIGN_APPROVED'::text, 'INSTALLATION_PENDING'::text, 'INSTALLED_UNVERIFIED'::text, 'COMMISSIONING'::text, 'ACCEPTED'::text, 'OPERATIONAL'::text]))),
    CONSTRAINT room_name_check CHECK (((length(name) >= 1) AND (length(name) <= 80))),
    CONSTRAINT room_occupancy_check CHECK (((occupancy >= 1) AND (occupancy <= 5000))),
    CONSTRAINT room_rev_check CHECK ((rev >= 1)),
    CONSTRAINT room_unit_check CHECK ((unit = ANY (ARRAY['m'::text, 'ft'::text])))
);

ALTER TABLE ONLY app.room FORCE ROW LEVEL SECURITY;

--
-- Name: room_issue; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.room_issue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    code text NOT NULL,
    key text NOT NULL,
    category text NOT NULL,
    check_name text NOT NULL,
    severity text NOT NULL,
    title text NOT NULL,
    rationale text NOT NULL,
    assets text[] DEFAULT '{}'::text[] NOT NULL,
    state text DEFAULT 'OPEN'::text NOT NULL,
    owner_role text,
    owner_id uuid,
    resolution jsonb,
    first_seen_rev integer NOT NULL,
    last_seen_rev integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT room_issue_category_check CHECK ((category = ANY (ARRAY['DESIGN_DEFICIENCY'::text, 'INSTALLATION_COMMISSIONING_DEFICIENCY'::text]))),
    CONSTRAINT room_issue_check CHECK (((state = 'RESOLVED'::text) = (resolution IS NOT NULL))),
    CONSTRAINT room_issue_severity_check CHECK ((severity = ANY (ARRAY['Critical'::text, 'High'::text, 'Medium'::text, 'Low'::text]))),
    CONSTRAINT room_issue_state_check CHECK ((state = ANY (ARRAY['OPEN'::text, 'RESOLVED'::text])))
);

ALTER TABLE ONLY app.room_issue FORCE ROW LEVEL SECURITY;

